using System.Windows;
using System.Windows.Controls;
using CommerceErp.Core;
namespace CommerceErp.Desktop;
public sealed class MasterBrowseWindow:Window
{
    private readonly LocalApiClient _api;private readonly ComboBox _kind=new(){Width=150,ItemsSource=new[]{"商品","映射","期初单","待映射"},SelectedIndex=0};private readonly TextBox _search=new(){Width=220};private readonly DataGrid _grid=new(){IsReadOnly=true,AutoGenerateColumns=true};private readonly TextBlock _status=new();private int _page=1;private bool _busy;
    public MasterBrowseWindow(LocalApiClient api,Func<object,Task>? select=null){_api=api;Title="基础资料分页检索";Width=1100;Height=700;MinWidth=800;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(18),Background=System.Windows.Media.Brushes.White};Content=root;_grid.MouseDoubleClick+=async(_,_)=>{if(_busy||select is null||_grid.SelectedItem is not{} item)return;_busy=true;try{await select(item);Close();}catch(Exception e){_status.Text="载入失败："+e.Message+"，请刷新后重试。";}finally{_busy=false;}};var bar=new WrapPanel();DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);bar.Children.Add(_kind);bar.Children.Add(_search);void Button(string title,Func<Task> action){var b=new Button{Content=title,Margin=new Thickness(8,0,0,8)};b.Click+=async(_,_)=>{if(_busy)return;try{_busy=true;bar.IsEnabled=false;await action();}catch(Exception e){_status.Text=e.Message;}finally{_busy=false;bar.IsEnabled=true;}};bar.Children.Add(b);}Button("查询",async()=>{_page=1;await RefreshAsync();});Button("上一页",async()=>{if(_page>1)_page--;await RefreshAsync();});Button("下一页",async()=>{_page++;await RefreshAsync();});DockPanel.SetDock(_status,Dock.Bottom);root.Children.Add(_status);root.Children.Add(_grid);}
    public async Task RefreshAsync(){var url=$"/api/master/{new[]{"skus","mappings","openings","unmapped"}[_kind.SelectedIndex]}/page?page={_page}&size=50&search={Uri.EscapeDataString(_search.Text)}";switch(_kind.SelectedIndex){case 0:Show(await _api.GetAsync<MasterPage<SkuProfile>>(url));break;case 1:Show(await _api.GetAsync<MasterPage<SkuMapping>>(url));break;case 2:Show(await _api.GetAsync<MasterPage<OpeningDocument>>(url));break;default:Show(await _api.GetAsync<MasterPage<UnmappedSku>>(url));break;}}
    private void Show<T>(MasterPage<T> p){_grid.ItemsSource=p.Items;_status.Text=$"第 {p.Page} 页 / 共 {p.Total} 条，每页 {p.PageSize} 条。双击记录载入维护页；独立查看时仅检索。";}
}
